import {
  DateInput,
  DateSegment,
  FieldError,
  Group,
  Label,
  Text,
  TimeField as AriaTimeField,
} from "react-aria-components";
import type {
  TimeFieldProps as AriaTimeFieldProps,
  TimeValue,
  ValidationResult,
} from "react-aria-components";
import type { ReactNode, Ref } from "react";
import { roleSize, type ControlSize } from "./controlSize";
import "./TimeField.css";

/** No `x-small` or `small`: a segment in a control of 32px or less is narrower than the 24px pointer target WCAG 2.5.8
    asks for, and flush segments cannot use its spacing exception. */
type TimeFieldSize = Exclude<ControlSize, "x-small" | "small">;

export interface TimeFieldProps
  extends Omit<AriaTimeFieldProps<TimeValue>, "className" | "children"> {
  /**
   * Size axis for the field wrapper.
   *
   * @default "medium"
   */
  size?: TimeFieldSize;
  /** Field label. */
  label?: string;
  /**
   * A `ContextualHelp` shown after the label, for a note the reader opens when they need it rather
   * than a `description` that is always on screen.
   */
  contextualHelp?: ReactNode;
  /** Helper text below the field. */
  description?: string;
  /** Message shown when validation fails. */
  errorMessage?: string | ((v: ValidationResult) => string);
  /** Additional class. sd-time-field is always preserved. */
  className?: string;
  /** Forwarded to the root time field DOM node. */
  ref?: Ref<HTMLDivElement>;
}

export function TimeField({
  size = "medium",
  label,
  contextualHelp,
  description,
  errorMessage,
  className,
  ref,
  ...props
}: TimeFieldProps) {
  return (
    <AriaTimeField
      {...props}
      ref={ref}
      className={className ? `sd-time-field ${className}` : "sd-time-field"}
    >
      {contextualHelp ? (
        <div className="sd-time-field__label-group">
          {label && <Label className={`sd-time-field__label sd-type-label-${roleSize(size)}`}>{label}</Label>}
          {contextualHelp}
        </div>
      ) : (
        label && <Label className={`sd-time-field__label sd-type-label-${roleSize(size)}`}>{label}</Label>
      )}
      <Group data-size={size} className={`sd-time-field__group sd-type-body-${roleSize(size)}`}>
        <DateInput className="sd-time-field__input">
          {(segment) => (
            <DateSegment segment={segment} className="sd-time-field__segment" />
          )}
        </DateInput>
      </Group>
      {description && (
        <Text slot="description" className={`sd-time-field__description sd-type-caption-${roleSize(size)}`}>
          {description}
        </Text>
      )}
      <FieldError className={`sd-time-field__error sd-type-caption-${roleSize(size)}`}>{errorMessage}</FieldError>
    </AriaTimeField>
  );
}

.sd-time-field {
  --sd-time-field-group-background-current: var(--sd-time-field-group-background);
  display: flex;
  flex-direction: column;
  gap: var(--sd-time-field-gap);
}
.sd-time-field[data-readonly] {
  --sd-time-field-group-background-current: var(--sd-time-field-group-background-readonly);
}

/* label-group — present only with `contextualHelp`: the label and its help trigger share one row. */
.sd-time-field__label-group {
  display: flex;
  align-items: center;
  gap: var(--sd-time-field-label-group-gap);
}

.sd-time-field__label {
  padding-inline: var(--sd-time-field-text-padding-inline);
  color: var(--sd-time-field-label-foreground);
}

.sd-time-field__group {
  --sd-time-field-group-radius-current: var(--sd-time-field-group-radius-medium);
  display: flex;
  align-items: center;
  width: 100%;
  padding-block: var(--sd-time-field-group-padding-block);
  background: var(--sd-time-field-group-background-current);
  color: var(--sd-time-field-group-foreground);
  border: var(--sd-time-field-group-border-width) solid var(--sd-time-field-group-border);
  border-radius: var(--sd-time-field-group-radius-current);
  corner-shape: superellipse(var(--sd-radius-curve));
  transition:
    border-color var(--sd-duration-moderate) var(--sd-easing-standard),
    box-shadow var(--sd-duration-moderate) var(--sd-easing-standard);
}

.sd-time-field__group[data-size="medium"] {
  --sd-time-field-group-radius-current: var(--sd-time-field-group-radius-medium);
  min-height: var(--sd-time-field-group-height-medium);
  padding-inline: var(--sd-time-field-group-padding-inline-medium);
  --sd-time-field-segment-padding-inline-current: var(--sd-time-field-segment-padding-inline-medium);
}

.sd-time-field__group[data-size="large"] {
  --sd-time-field-group-radius-current: var(--sd-time-field-group-radius-large);
  min-height: var(--sd-time-field-group-height-large);
  padding-inline: var(--sd-time-field-group-padding-inline-large);
  --sd-time-field-segment-padding-inline-current: var(--sd-time-field-segment-padding-inline-large);
}
.sd-time-field__group[data-size="x-large"] {
  --sd-time-field-group-radius-current: var(--sd-time-field-group-radius-x-large);
  min-height: var(--sd-time-field-group-height-x-large);
  padding-inline: var(--sd-time-field-group-padding-inline-x-large);
  --sd-time-field-segment-padding-inline-current: var(--sd-time-field-segment-padding-inline-x-large);
}

.sd-time-field__group[data-hovered] {
  border-color: var(--sd-time-field-group-border-hover);
}

.sd-time-field__group[data-focus-within] {
  border-color: var(--sd-time-field-group-border-focus);
  box-shadow: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}

.sd-time-field__group[data-invalid] {
  border-color: var(--sd-time-field-group-border-invalid);
}
.sd-time-field__group[data-invalid][data-focus-within] {
  box-shadow: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-time-field-group-border-invalid) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}

.sd-time-field__group[data-disabled] {
  opacity: var(--sd-state-disabled);
  cursor: not-allowed;
}

.sd-time-field__input {
  display: flex;
  align-items: center;
  align-self: stretch;
  flex: 1;
  min-width: 0;
  padding-block: var(--sd-time-field-input-padding-block);
  outline: none;
}

.sd-time-field__segment {
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--sd-time-field-segment-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
  color: var(--sd-time-field-segment-foreground);
  outline: none;
}

/* Editable segments (hour/minute/…) fill the input height for a control-height tap
   target (WCAG 2.5.8) + a full-height focus chip; literal separators (":") stay compact. */
.sd-time-field__segment:not([data-type="literal"]) {
  align-self: stretch;
  padding-inline: var(--sd-time-field-segment-padding-inline-current);
}

.sd-time-field__segment[data-placeholder] {
  color: var(--sd-time-field-segment-foreground-placeholder);
}

.sd-time-field__segment[data-focused] {
  background: var(--sd-time-field-segment-background-focus);
  color: var(--sd-time-field-segment-foreground-focus);
}

.sd-time-field__description {
  padding-inline: var(--sd-time-field-text-padding-inline);
  color: var(--sd-time-field-description-foreground);
}

.sd-time-field__error {
  padding-inline: var(--sd-time-field-text-padding-inline);
  color: var(--sd-time-field-error-foreground);
}
